import React, { useState } from "react";
import { API } from "../config";

export default function Home() {
  const [vehicle, setVehicle] = useState("");
  const [challans, setChallans] = useState([]);

  const fetchChallans = async () => {
    if (!vehicle) return alert("Enter vehicle number");
    const res = await fetch(`${API}/challan/vehicle/${vehicle}`);
    const data = await res.json();
    if (data.error) alert(data.error);
    else setChallans(data);
  };

  return (
    <div>
      <h3>Search Challans by Vehicle Number</h3>
      <input
        placeholder="Enter vehicle number"
        value={vehicle}
        onChange={(e) => setVehicle(e.target.value)}
      />
      <button onClick={fetchChallans}>Search</button>

      {challans.length > 0 && (
        <table border="1" cellPadding="6" style={{ marginTop: 10 }}>
          <thead>
            <tr>
              <th>#</th>
              <th>Vehicle</th>
              <th>Cause</th>
              <th>Fine</th>
              <th>Status</th>
              <th>Issue Date</th>
              <th>Due Date</th>
              <th>Address</th>
            </tr>
          </thead>
          <tbody>
            {challans.map((c, i) => (
              <tr key={c._id}>
                <td>{i + 1}</td>
                <td>{c.vehicleNumber}</td>
                <td>{c.cause}</td>
                <td>{c.fine}</td>
                <td>{c.status}</td>
                <td>{c.issueDate}</td>
                <td>{c.dueDate}</td>
                <td>{c.address}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
}
